/**
 * Where product files and store images are kept.
 *
 * - Locally: plain files on disk (SELLER_FILES_DIR / SELLER_MEDIA_DIR).
 * - Hosted on Supabase (SUPABASE_URL + SUPABASE_SERVICE_ROLE_KEY set):
 *   Supabase Storage. Product files go to a PRIVATE bucket and are only ever
 *   handed out as short-lived signed links; store images go to a public one.
 *
 * Every id is generated by the server (fil_… / med_…), never taken from a
 * request, so paths cannot be steered by a client.
 */
import { createReadStream, existsSync, mkdirSync, statSync, unlinkSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'
import type { Response } from 'express'

export type Kind = 'files' | 'media'

const supaUrl = (process.env.SUPABASE_URL ?? '').replace(/\/+$/, '')
const supaKey = process.env.SUPABASE_SERVICE_ROLE_KEY ?? ''
export const BUCKETS: Record<Kind, string> = {
  files: process.env.SELLER_FILES_BUCKET ?? 'seller-files',
  media: process.env.SELLER_MEDIA_BUCKET ?? 'seller-media',
}
export const usingSupabaseStorage = Boolean(supaUrl && supaKey)

export interface Blobs {
  put(kind: Kind, id: string, body: Buffer, type: string): Promise<void>
  remove(kind: Kind, id: string): Promise<void>
  exists(kind: Kind, id: string): Promise<boolean>
  /** Sends the object to the client (a redirect to a signed URL when hosted). */
  send(kind: Kind, id: string, res: Response, opts: { fileName?: string; type: string; cache: string }): Promise<void>
}

function diskBlobs(dirs: Record<Kind, string>): Blobs {
  for (const d of Object.values(dirs)) mkdirSync(d, { recursive: true })
  return {
    async put(kind, id, body) {
      writeFileSync(join(dirs[kind], id), body)
    },
    async remove(kind, id) {
      try {
        unlinkSync(join(dirs[kind], id))
      } catch {
        /* already gone */
      }
    },
    async exists(kind, id) {
      return existsSync(join(dirs[kind], id))
    },
    async send(kind, id, res, { fileName, type, cache }) {
      const path = join(dirs[kind], id)
      res.set({ 'Cache-Control': cache, 'Content-Type': type, 'Content-Length': String(statSync(path).size), 'X-Content-Type-Options': 'nosniff' })
      if (fileName) res.set('Content-Disposition', `attachment; filename="${fileName}"`)
      createReadStream(path).pipe(res)
    },
  }
}

function supabaseBlobs(): Blobs {
  const h = { Authorization: `Bearer ${supaKey}`, apikey: supaKey }
  const obj = (kind: Kind, id: string) => `${supaUrl}/storage/v1/object/${BUCKETS[kind]}/${id}`
  return {
    async put(kind, id, body, type) {
      const r = await fetch(obj(kind, id), { method: 'POST', headers: { ...h, 'Content-Type': type, 'x-upsert': 'false' }, body })
      if (!r.ok) throw new Error(`Storage upload failed (${r.status}): ${(await r.text()).slice(0, 200)}`)
    },
    async remove(kind, id) {
      await fetch(obj(kind, id), { method: 'DELETE', headers: h }).catch(() => {})
    },
    async exists(kind, id) {
      const r = await fetch(`${supaUrl}/storage/v1/object/info/${BUCKETS[kind]}/${id}`, { headers: h })
      return r.ok
    },
    async send(kind, id, res, { fileName }) {
      if (kind === 'media') return void res.redirect(302, `${supaUrl}/storage/v1/object/public/${BUCKETS.media}/${id}`)
      // Private file: a signed link valid for 5 minutes, forcing a download.
      const r = await fetch(`${supaUrl}/storage/v1/object/sign/${BUCKETS.files}/${id}`, {
        method: 'POST',
        headers: { ...h, 'Content-Type': 'application/json' },
        body: JSON.stringify({ expiresIn: 300 }),
      })
      if (!r.ok) return void res.status(410).json({ error: 'This file is no longer available.' })
      const { signedURL } = (await r.json()) as { signedURL: string }
      const u = new URL(`${supaUrl}/storage/v1${signedURL}`)
      u.searchParams.set('download', fileName ?? 'download')
      res.set('Cache-Control', 'private, no-store')
      res.redirect(302, u.toString())
    },
  }
}

export function makeBlobs(dirs: Record<Kind, string>): Blobs {
  return usingSupabaseStorage ? supabaseBlobs() : diskBlobs(dirs)
}
